# integration_cpp_reference ----
## Setup ----
# Values from the C++ build of FIMS, made by
# data-raw/integration_cpp_reference.R. Each configuration keeps the parameter
# tibble C++ FIMS was given, so both models start from the same input.
cpp_reference <- readRDS(
  testthat::test_path("fixtures", "integration_cpp_reference.RDS")
)
data("data_big")
data_4_model <- FIMSFrame(data_big)
data_von_bertalanffy <- data_big |>
  dplyr::filter(type != "weight_at_age") |>
  FIMSFrame()

# At the same parameter values the 2 models differ by at most about 5e-13
# relative, from the order of floating-point operations. 1e-10 leaves room for
# other platforms, and a change to the model's equations moves values by far
# more.
tolerance <- 1e-10

## IO correctness ----
test_that("setup_default_parameters() gives the C++ FIMS defaults", {
  #' @description Test that the default parameters for data_big equal those C++ FIMS was given.
  expect_equal(
    object = setup_default_parameters(data = data_4_model),
    expected = cpp_reference[["default"]][["parameters"]]
  )
  #' @description Test that the default parameters without weight-at-age data equal those C++ FIMS was given.
  expect_equal(
    object = setup_default_parameters(data = data_von_bertalanffy),
    expected = cpp_reference[["von_bertalanffy"]][["parameters"]]
  )
})

test_that("the default model matches C++ FIMS at the starting values", {
  differences <- compare_with_cpp(cpp_reference[["default"]], data_4_model)

  #' @description Test that every estimated value in C++ FIMS has 1 estimated value in the RTMB model.
  expect_equal(
    object = differences[["n_unmatched"]],
    expected = 0
  )
  # C++ FIMS holds the recruitment log_sd of 0.1 as 0.10000000000000007, so
  # the starting values agree to 1e-14, not exactly.
  #' @description Test that the RTMB model starts from the C++ FIMS starting values.
  expect_lt(
    object = differences[["start"]],
    expected = 1e-14
  )
  #' @description Test that the joint negative log-likelihood equals C++ FIMS.
  expect_lt(
    object = differences[["jnll"]],
    expected = tolerance
  )
  #' @description Test that each negative log-likelihood component equals C++ FIMS.
  expect_lt(
    object = differences[["nll_components"]],
    expected = tolerance
  )
  #' @description Test that the gradient over fixed and random effects equals C++ FIMS.
  expect_lt(
    object = differences[["gradient"]],
    expected = tolerance
  )
  # Written as "not less than" so that a NaN difference is listed too.
  #' @description Test that population, fleet and composition reports equal C++ FIMS.
  expect_equal(
    object = names(which(!(differences[["reports"]] < tolerance))),
    expected = character(0)
  )
})

test_that("the default model's Laplace approximation matches C++ FIMS", {
  cpp <- cpp_reference[["default"]][["laplace"]]
  rtmb <- rtmb_objective(
    cpp_reference[["default"]][["parameters"]], data_4_model,
    laplace = TRUE
  )
  obj <- rtmb[["obj"]]
  cpp_order <- order_like_cpp(
    rtmb_parameter_keys(
      names(obj[["par"]]), rtmb[["input"]][["parameter_table"]]
    ),
    cpp[["values"]]
  )
  #' @description Test that every C++ FIMS fixed effect has 1 fixed effect in the RTMB model.
  expect_equal(
    object = sort(cpp_order),
    expected = seq_along(obj[["par"]])
  )
  cpp_values <- numeric(length(cpp_order))
  cpp_values[cpp_order] <- cpp[["values"]][["value"]]

  #' @description Test that the Laplace approximation of the marginal negative log-likelihood equals C++ FIMS.
  expect_lt(
    object = max_relative_difference(obj[["fn"]](cpp_values), cpp[["objective"]]),
    expected = tolerance
  )
  #' @description Test that the gradient of the Laplace approximation equals C++ FIMS.
  expect_lt(
    object = max_relative_difference(
      as.vector(obj[["gr"]](cpp_values))[cpp_order], cpp[["values"]][["gradient"]]
    ),
    expected = tolerance
  )
})

test_that("von Bertalanffy-Schnute growth matches C++ FIMS at the start", {
  differences <- compare_with_cpp(
    cpp_reference[["von_bertalanffy"]], data_von_bertalanffy
  )

  #' @description Test that every estimated value in C++ FIMS has 1 estimated value in the RTMB model with von Bertalanffy-Schnute growth.
  expect_equal(
    object = differences[["n_unmatched"]],
    expected = 0
  )
  #' @description Test that the RTMB model with von Bertalanffy-Schnute growth starts from the C++ FIMS starting values.
  expect_lt(
    object = differences[["start"]],
    expected = 1e-14
  )
  #' @description Test that the joint negative log-likelihood with von Bertalanffy-Schnute growth equals C++ FIMS.
  expect_lt(
    object = differences[["jnll"]],
    expected = tolerance
  )
  #' @description Test that each negative log-likelihood component with von Bertalanffy-Schnute growth equals C++ FIMS.
  expect_lt(
    object = differences[["nll_components"]],
    expected = tolerance
  )
  #' @description Test that the gradient with von Bertalanffy-Schnute growth, including the growth parameters, equals C++ FIMS.
  expect_lt(
    object = differences[["gradient"]],
    expected = tolerance
  )
  #' @description Test that growth, population, fleet and composition reports with von Bertalanffy-Schnute growth equal C++ FIMS.
  expect_equal(
    object = names(which(!(differences[["reports"]] < tolerance))),
    expected = character(0)
  )
})

test_that("the fixed-effect model matches C++ FIMS at the C++ estimates", {
  cpp <- cpp_reference[["fixed_effects_fit"]]
  rtmb <- rtmb_objective(cpp[["parameters"]], data_4_model)
  obj <- rtmb[["obj"]]
  cpp_order <- order_like_cpp(
    rtmb_parameter_keys(
      names(obj[["par"]]), rtmb[["input"]][["parameter_table"]]
    ),
    cpp[["values"]]
  )
  #' @description Test that every C++ FIMS fixed effect has 1 fixed effect in the RTMB model.
  expect_equal(
    object = sort(cpp_order),
    expected = seq_along(obj[["par"]])
  )
  cpp_estimates <- numeric(length(cpp_order))
  cpp_estimates[cpp_order] <- cpp[["values"]][["estimate"]]

  #' @description Test that the negative log-likelihood at the C++ FIMS estimates equals the C++ FIMS objective.
  expect_lt(
    object = max_relative_difference(
      obj[["fn"]](cpp_estimates), cpp[["objective"]]
    ),
    expected = tolerance
  )
  # The RTMB and C++ fits stop at slightly different points, so standard
  # errors are compared at the C++ estimates. This tests the model rather than
  # the optimizer.
  sdreport <- RTMB::sdreport(obj, par.fixed = cpp_estimates)
  #' @description Test that fixed-effect standard errors at the C++ FIMS estimates equal C++ FIMS.
  expect_lt(
    object = max_relative_difference(
      sqrt(diag(sdreport[["cov.fixed"]]))[cpp_order],
      cpp[["values"]][["standard_error"]]
    ),
    expected = tolerance
  )
})

test_that("a fixed-effect fit reaches the C++ FIMS estimates", {
  skip_if(
    Sys.getenv("RUN_SLOW_TESTS") != "true",
    "Skipping: RUN_SLOW_TESTS is not set to true."
  )
  cpp <- cpp_reference[["fixed_effects_fit"]]
  input <- initialize_fims(cpp[["parameters"]], data = data_4_model)
  fit <- fit_fims(input, optimize = TRUE)
  opt <- get_opt(fit)
  cpp_order <- order_like_cpp(
    rtmb_parameter_keys(names(opt[["par"]]), input[["parameter_table"]]),
    cpp[["values"]]
  )

  #' @description Test that the objective at the RTMB estimates equals the C++ FIMS objective.
  expect_lt(
    object = max_relative_difference(opt[["objective"]], cpp[["objective"]]),
    expected = 1e-8
  )
  # Relative to at least 1, because estimates near 0, such as recruitment
  # deviations, have no useful relative difference. The largest difference is
  # about 1e-5, or 7e-5 standard errors, depending on where nlminb stops.
  #' @description Test that the RTMB estimates equal the C++ FIMS estimates.
  expect_lt(
    object = max_relative_difference(
      opt[["par"]][cpp_order], cpp[["values"]][["estimate"]],
      floor = 1
    ),
    expected = 1e-4
  )

  # Standard errors of derived quantities need every ADREPORT, so they are
  # checked in this slow test.
  obj <- get_obj(fit)
  cpp_estimates <- numeric(length(cpp_order))
  cpp_estimates[cpp_order] <- cpp[["values"]][["estimate"]]
  sdreport <- RTMB::sdreport(obj, par.fixed = cpp_estimates)
  derived <- tibble::tibble(
    name = names(sdreport[["value"]]),
    value = unname(sdreport[["value"]]),
    standard_error = unname(sdreport[["sd"]])
  ) |>
    dplyr::filter(name %in% cpp[["derived"]][["name"]]) |>
    dplyr::mutate(position = dplyr::row_number(), .by = "name")
  derived <- dplyr::left_join(
    cpp[["derived"]], derived,
    by = c("name", "position"), suffix = c("_cpp", "_rtmb")
  )
  #' @description Test that derived quantities at the C++ FIMS estimates, such as spawning biomass, equal C++ FIMS.
  expect_lt(
    object = max_relative_difference(
      derived[["value_rtmb"]], derived[["value_cpp"]]
    ),
    expected = tolerance
  )
  #' @description Test that standard errors of derived quantities at the C++ FIMS estimates equal C++ FIMS.
  expect_lt(
    object = max_relative_difference(
      derived[["standard_error_rtmb"]], derived[["standard_error_cpp"]]
    ),
    expected = tolerance
  )
})

